RETRYABLE = {429, 500, 502, 503, 504}

def run_client(scripted_status, retry_all, max_attempts=5):
    requests = 0
    while requests < max_attempts:
        requests += 1
        if scripted_status == 200:
            return requests, "success"
        if not retry_all and scripted_status not in RETRYABLE:
            return requests, f"gave up immediately on {scripted_status}"
    return requests, f"still failing after {requests} attempts"

for status, label in [(400, "bad request - the request itself is wrong"),
                      (401, "unauthorized - credentials are wrong"),
                      (503, "service unavailable - server-side, transient")]:
    buggy, b_out = run_client(status, retry_all=True)
    fixed, f_out = run_client(status, retry_all=False)
    print(f"status {status} ({label}):")
    print(f"  retry-everything client: {buggy} requests, {b_out}")
    print(f"  status-aware client    : {fixed} requests, {f_out}")
print("a 400 will never turn into a 200 because you asked five times;")
print("retrying it only multiplies load and delays the real error report")

class MiniBreaker:
    def __init__(self): self.fails, self.open = 0, False
    def call(self, ok):
        if self.open:
            return "rejected"
        if ok:
            self.fails = 0
            return "success"
        self.fails += 1
        if self.fails >= 2:
            self.open = True
        return "failure"

calls = [("payments", False), ("payments", False),
         ("search", True), ("search", True), ("search", True)]

print("design A - ONE global breaker for all dependencies:")
g = MiniBreaker()
for dep, ok in calls:
    print(f"  {dep:9} -> {g.call(ok)}")
print("  payments being down got SEARCH rejected 3 times: guilt by association")
print()
print("design B - one breaker PER dependency:")
breakers = {"payments": MiniBreaker(), "search": MiniBreaker()}
for dep, ok in calls:
    print(f"  {dep:9} -> {breakers[dep].call(ok)}")
print("  search succeeds throughout; only the sick dependency is cut off")

queue = ["order-101", "POISON", "order-102", "order-103"]
deliveries = {}
processed = []

def handle(item):
    if item == "POISON":
        raise ValueError("malformed payload")
    processed.append(item)

print("consumer with no poison handling; a supervisor restarts it after each crash:")
for restart in range(1, 6):
    try:
        while queue:
            item = queue[0]
            deliveries[item] = deliveries.get(item, 0) + 1
            handle(item)
            queue.pop(0)
        break
    except ValueError:
        print(f"  crash #{restart}: died on {queue[0]!r} - item NOT removed, "
              f"will be redelivered")
print(f"deliveries per item: {deliveries}")
print(f"processed: {processed}")
print("order-102 and order-103 are fine and were never touched: one bad")
print("item at the head of the queue is a full outage for everything behind it")

ITEMS = ["a", "b", "POISON", "c", "d", "e"]

def dies_on_poison(items):
    processed, restarts = [], 0
    queue = list(items)
    while queue and restarts < 10:
        try:
            while queue:
                if queue[0] == "POISON":
                    raise ValueError("boom")
                processed.append(queue.pop(0))
            break
        except ValueError:
            restarts += 1
    return processed, restarts, len(queue)

def skips_and_logs(items):
    processed, log = [], []
    for item in items:
        if item == "POISON":
            log.append(f"SKIPPED {item}: malformed payload, id recorded")
        else:
            processed.append(item)
    return processed, log

p1, r1, left1 = dies_on_poison(ITEMS)
p2, log2 = skips_and_logs(ITEMS)
print(f"queue: {ITEMS}")
print(f"die-on-error : processed {len(p1)} {p1}, restarts {r1}, stuck with {left1} items")
print(f"skip-and-log : processed {len(p2)} {p2}")
for line in log2:
    print(f"               log: {line}")
print("skipping is not free either: the skipped item's work silently never")
print("happens, and strict ordering is broken for everything after it.")
print("the honest trade is: die = nothing is lost but nothing moves;")
print("skip = everything moves but one thing is lost ON THE RECORD")

store = {"counter": 10}

# scripted interleaving of two replicas incrementing the same counter
trace = []
reads = {}
for node in ("A", "B"):
    reads[node] = store["counter"]
    trace.append(f"{node} reads counter = {reads[node]}")
for node in ("A", "B"):
    store["counter"] = reads[node] + 1
    trace.append(f"{node} writes counter = {reads[node] + 1} (last writer wins)")

for line in trace:
    print(" ", line)
print(f"final value: {store['counter']}")
print("two increments were issued; the counter moved once. no error was")
print("raised anywhere - last-writer-wins loses updates silently, which")
print("is why it is a data-loss bug and not a crash bug")

def dominates(a, b):
    return all(a[k] >= b[k] for k in a) and any(a[k] > b[k] for k in a)

def compare(a, b):
    if a == b:
        return "identical"
    if dominates(a, b):
        return "a is NEWER (b's writes are included)"
    if dominates(b, a):
        return "b is NEWER (a's writes are included)"
    return "CONCURRENT - neither saw the other's write: a real conflict"

va = {"A": 1, "B": 0}    # A wrote once, has not seen B
vb = {"A": 0, "B": 1}    # B wrote once, has not seen A
print(f"A's version vector: {va}")
print(f"B's version vector: {vb}")
print(f"compare: {compare(va, vb)}")
merged = {k: max(va[k], vb[k]) for k in va}
va2 = {"A": 2, "B": 1}   # A later reads B's write, then writes again
print(f"after A reads B and writes again: {va2}")
print(f"compare vs B: {compare(va2, vb)}")
print(f"merged vector for the concurrent pair: {merged}")
print("the vectors do not resolve the conflict - they DETECT it, exactly,")
print("where a single timestamp would have picked a winner by clock luck")

